import{_ as r,o as i,c,a2 as a,j as t,a as o,t as l}from"./chunks/framework.BEUshCVJ.js";const m=JSON.parse('{"title":"本地化指南","description":"","frontmatter":{},"headers":[],"relativePath":"zh/contribute/localization.md","filePath":"zh/contribute/localization.md","lastUpdated":1792973503000}'),n={name:"zh/contribute/localization.md"};function s(d,e,h,_,u,p){return i(),c("div",null,[e[4]||(e[4]=a('<h1 id="本地化指南" tabindex="-1">本地化指南 <a class="header-anchor" href="#本地化指南" aria-label="Permalink to &quot;本地化指南&quot;">​</a></h1><p>本页说明 MeetCue 的英文和简体中文文字是如何组织的，以及修改时如何让两种语言保持同步。</p><h2 id="文字存放位置" tabindex="-1">文字存放位置 <a class="header-anchor" href="#文字存放位置" aria-label="Permalink to &quot;文字存放位置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文字</th><th>文件</th></tr></thead><tbody><tr><td>界面、托盘菜单、通知</td><td><code>app/ui/locales/en.json</code>、<code>app/ui/locales/zh-CN.json</code></td></tr><tr><td>错误标题与解决办法</td><td><code>crates/core/data/errors.json</code>（每条同时包含两种语言）</td></tr><tr><td>文档</td><td>英文在 <code>docs/</code>，中文在 <code>docs/zh/</code>，文件名相同</td></tr><tr><td>模型提示词</td><td><code>crates/pipeline/prompts/*.txt</code>（英文；输出语言作为参数传入）</td></tr></tbody></table><p>代码、注释和提交信息使用英文。</p><h2 id="修改界面文字" tabindex="-1">修改界面文字 <a class="header-anchor" href="#修改界面文字" aria-label="Permalink to &quot;修改界面文字&quot;">​</a></h2>',6)),t("ol",null,[e[2]||(e[2]=t("li",null,[o("在同一个提交中修改 "),t("strong",null,"两个"),o(" 语言文件里的同一个键。")],-1)),t("li",null,[e[0]||(e[0]=o("整句翻译并使用占位符，例如 ",-1)),t("code",null,'"已讲 '+l(d.done)+"/"+l(d.total)+'"',1),e[1]||(e[1]=o("。不要用片段拼句子，两种语言的语序不同。",-1))]),e[3]||(e[3]=a("<li>涉及数量时，英文使用 i18next 的复数键（<code>_one</code>、<code>_other</code>）。中文只需要 <code>_other</code>，但两个键都要保留，让两个文件一致。</li><li>运行 <code>npm run check:locales</code>。如果某个键只存在于一个文件中，或有空值，检查会失败。</li><li>用 <code>npm run dev:mock</code> 检查两种语言下的布局。英文通常更长，按钮和表头要留出余量。</li>",3))]),e[5]||(e[5]=a('<h2 id="修改错误信息" tabindex="-1">修改错误信息 <a class="header-anchor" href="#修改错误信息" aria-label="Permalink to &quot;修改错误信息&quot;">​</a></h2><p>同时修改 <code>errors.json</code> 中该条目的 <code>en</code> 和 <code>zh-CN</code> 字段。解决办法用一句话告诉用户该怎么做。构建文档时会根据这个文件重新生成错误码页面。</p><h2 id="修改文档" tabindex="-1">修改文档 <a class="header-anchor" href="#修改文档" aria-label="Permalink to &quot;修改文档&quot;">​</a></h2><ol><li>在同一个 Pull Request 中修改英文页面和 <code>docs/zh/</code> 下同路径的页面。</li><li>保持相同的二级标题和顺序。<code>docs/scripts/check-i18n.mjs</code> 会检查每个页面在两种语言下都存在，且 <code>##</code> 标题数量相同。</li><li>链接需要指向某个标题时，在两种语言里都为标题写明确的 id，例如 <code>## 快捷键没反应 {#shortcuts}</code>，保证锚点一致。</li></ol><h2 id="写作规范" tabindex="-1">写作规范 <a class="header-anchor" href="#写作规范" aria-label="Permalink to &quot;写作规范&quot;">​</a></h2><ul><li>每页第一句说明这页解决什么问题。</li><li>标题按任务或用户看到的现象命名：写“连接麦克风”，不写“麦克风”。</li><li>步骤用编号列表，每步一个动作。</li><li>按钮和菜单名称与界面完全一致，并加粗。</li><li>不提及具体的国家、城市或“推荐区域”。端点只用主机名标识。</li></ul>',6))])}const T=r(n,[["render",s]]);export{m as __pageData,T as default};
